ga2i(){return"\u0936\u094d\u0930\u0947\u0923\u0940"},
ga2t(){return"\u0928\u094b\u091f (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)"},
gXe(){return"\u092a\u0941\u0937\u094d\u091f\u093f \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f RESET \u091f\u093e\u0907\u092a \u0915\u0930\u0947\u0902"},
gX7(){return"\u0938\u092c \u0915\u0941\u091b \u092e\u093f\u091f\u093e\u090f\u0902"},
Xd(a){return"\u0930\u0940\u0938\u0947\u091f \u0935\u093f\u092b\u0932: "+a},
